	m_lastregion = 3;
	m_alt = 0.0f;
	m_dT = 0.0f;
	SetLookDir(&CPnt3D::unit_nz, 0.0f);
	m_mass = 90.0f;
	m_waterdepth = 0.0f;
	RotateHead(0.0f, 0.0f);
	m_zoomval = 500.0f;
	CPnt3D toe(1.09f, 0.0f, 0.0f);
	PartInSpace(m_lfoot, &toe, &m_footL, NULL);
	PartInSpace(m_rfoot, &toe, &m_footR, NULL);
	m_last_foot = 2;
	m_throttleQuadrant = -1;
	m_prev_throttleQuadrant = -1;
